; ========================================================================================
; TEMPLATE 999: entry_routine -- 5210 copied code/data bytes; source L751..L2728
; ========================================================================================
;
; LOWEST is used to calculate address offsets within ENTRY_ROUTINE
;
lib_index_end:
;
;
;
; CODE-GENERATION TEMPLATES - the 'building-blocks' of a compiled task
;
; ENTRY_ROUTINE is at the start of EVERY compiled task.
;
entry_routine:
        bra.s      initiali  ; src L758: bra.s initiali  altered v5.36; target $00000952
        dc.b       $35,$2E,$33,$37  ; src L759: dc.b vers  Library release number; ASCII |5.37|
        dc.w       $4AFB  ; src L760: dc.w task_marker; ASCII |J.|
task_name:
        dc.w       $000C  ; src L761: task_name dc.w 12
        dc.b       $54,$55,$52,$42,$4F,$20,$36,$38,$30,$30,$38,$20  ; src L762: dc.b 'TURBO 68008 '; ASCII |TURBO 68008 |
copyright:
        dc.b       $20,$7F,$20,$32,$30,$30,$30,$20,$54,$68,$65,$20,$54,$75,$72,$62  ; src L763: copyright dc.b ' \x7F 2000 The Turbo Team.',10; ASCII | . 2000 The Turb|
        dc.b       $6F,$20,$54,$65,$61,$6D,$2E,$0A  ; continued data; ASCII |o Team..|
;
; These pointers implement the LINK semaphores in composite tasks.
; The offsets are FIXED and start at byte 46 in the task.
;
global_external_list:
        dc.l       $00000000  ; src L769: global_external_list dc.l 0 Loaded during initialise   (+46)
my_module_number:
        dc.w       $FFFF  ; src L770: my_module_number dc.w -1 Loaded during initialise   (+50)
module_table_base:
        dc.l       $00000000  ; src L771: module_table_base dc.l 0 Patched by LINK_LOAD   (+52)
owner_id:
        dc.l       $FFFFFFFF  ; src L772: owner_ID  dc.l -1 Patched (or not) by LINK_LOAD (+56)
globals_set:
        dc.b       $00  ; src L773: globals_set dc.b 0 Flag set by last_global   (+60)
externals_set:
        dc.b       $00  ; src L774: externals_set dc.b 0 Flag set by LINK_LOAD   (+61)
;
; Efficiency (and the optimised code) dictates that SNOOZING MUST BE EVEN.
;
snoozing:
        dc.b       $00  ; src L778: snoozing  dc.b 0 Flag set by SNOOZE    (+62)
module_in_use:
        dc.b       $00  ; src L779: module_in_use dc.b 0 Flag set by external module   (+63)
head_pointer:
        dc.l       $00000000  ; src L780: head_pointer dc.l 0 Pointer to latest heap frame   (+64)
master_job_base:
        dc.l       $00000000  ; src L781: master_job_base dc.l 0 Base address of master job   (+68)
;
; The master job is the task which initiated a series of EXTERNAL calls,
; which may be mutually recursive, it is the 'task in control'
;
initiali:
        bra.s      initialise  ; src L787: initiali  bra initialise needed for 1st short branch; target $00000992
;
; When an error occurs a compiled task tries to call an error-handler,
; if any, written in SuperBASIC threaded code. If the local error-handler
; can't help, the error is propagated to the global handler; if neither
; can help, a fatal error results. N.B. After a RETRY the compiled code
; re-sets the bounds of the area containing all LOCAL variables and
; GLOBAL arrays - so don't RETRY back into a procedure or function
; after it has been left. The GLOBAL bounds are adjusted by STACKATRUCK
; after re-sizing of existing arrays or creation of new ones.
;
; The next 3 long words hold addresses copied from THREAD
;
local_when:
        dc.l       $00000000  ; src L802: local_when dc.l 0 Pointer to the last local WHEN routine
global_when:
        dc.l       $00000000  ; src L803: global_when dc.l 0 Pointer to the last global WHEN handler
retry_point:
        dc.l       $00000000  ; src L804: retry_point dc.l 0 'Here' for RETRY_HERE or RETRY_HERE 0
;
; The register dump area is loaded by RETRY_HERE & DIM. Dumped values
; are restored to registers by RETRY, WHEN_ERROR_0/1 and CONTINUE.
;
retry_dump:
        dc.l       $00000000  ; src L809: retry_dump dc.l 0 For MATHS
        dc.l       $00000000  ; src L810: dc.l 0 For DATA
        dc.l       $00000000  ; src L811: dc.l 0 For BASE
        dc.l       $00000000  ; src L812: dc.l 0 For SP
