        cmpa.l     a3,a4  ; src L955: cmpa.l a3,a4  more to look at? . .
        ble.s      ex_2  ; src L956: ble ex_2  . . yes; target $00000a62
        bra.s      next_name1  ; src L957: bra next_name1 not found; target $00000a7e
