;
; These distinctive routines are the MEGA-MOVER; a TURBO TRADEMARK!
; The code is cunningly scattered around to make hacking difficult,
; but extra-keen people can always find this routine with TRACE.
;
; UPDOWN_MOVE is the only entry-point that can move overlapping data
; 'UP' memory. It does this pretty slowly - GET_UP, above, may be faster.
;
updown_move:
        tst.l      d0  ; src L1325: updown_move tst.l d0
        beq.s      moved  ; src L1326: beq.s moved; target $00000d74
        bpl.s      move_how_many  ; src L1327: bpl move_how_many; target $00000dd0
        neg.l      d0  ; src L1328: neg.l d0
upd_m1:
        adda.l     d0,a0  ; src L1329: upd_m1  adda.l d0,a0  Entry for redimensioning of LOCals
        adda.l     d0,a4  ; src L1330: adda.l d0,data
        tst.w      d0  ; src L1331: tst.w d0
        beq.s      shove_l  ; src L1332: beq.s shove_l; target $00000d90
shove_em:
        subq.w     #1,d0  ; src L1333: shove_em  subq.w #1,d0  Adjust for DBRA
shove_b:
        move.b     -(a0),-(a4)  ; src L1334: shove_b move.b -(a0),-(data)
        dbra       d0,shove_b  ; src L1335: dBra d0,shove_b; target $00000d88
        addq.w     #1,d0  ; src L1336: addq.w #1,d0  Make low word 0
shove_l:
        tst.l      d0  ; src L1337: shove_l tst.l d0
        beq.s      moved  ; src L1338: beq.s moved; target $00000d74
        SUB.l      #$00010000,d0  ; src L1339: sub.l #65536,d0
        bra.s      shove_em  ; src L1340: bra.s shove_em; target $00000d86
dunnit:
        rts          ; src L1341: dunnit  rts; return via CPU stack
;
; Minimove: for strings that are hard to mega-move - 1-31 bytes long,
; or one - but not both - of source and destination addresses odd.
; N.B. This is NOT a library entry-point!
;
one_odd:
        lea        $84a4(a6),a2  ; src L1348: lea.l odd_block-lowest(base),a2   Retn point til last loop
        lea        $839c(a6),a3  ; src L1349: lea.l byte_table-lowest(base),a3
odd_block:
        moveq      #$20,d1  ; src L1351: moveq #32,d1
        SUB.l      d1,d0  ; src L1352: sub.l d1,d0
        bls.s      move_last  ; src L1353: bls.s move_last Do the remaining bytes; target $00000dae
        jmp        (a3)  ; src L1354: jmp (a3)  Move a block of 32 bytes
move_last:
        add.l      d1,d0  ; src L1356: add.l d1,d0  Restore count
;
minimove:
        SUB.l      d0,d1  ; src L1359: sub.l d0,d1  D1 is No. of moves to be skipped
        move.l     (a7)+,a2  ; src L1360: move.l (a7)+,a2 Return address
        add.l      d1,d1  ; src L1361: add.l d1,d1  Scale for two-byte instructions
        lea        $83e6(a6),a3  ; src L1362: lea.l byte_table+74-lowest(base),a3
        jmp        $b6(a3,d1.l)  ; src L1363: jmp -74(a3,d1.l) The 74s add extra misdirection!
;
; MEGA_CHECK; copy a string of D0.W bytes from (A0) to (DATA),
; after ensuring that there's plenty of room on the heap.
;
mega_check:
        ext.l      d0  ; src L1369: ext.l d0
