        SUBa.l     d0,a2  ; src L1371: suba.l d0,a2  If D0 is negative check always says 'OK'
        cmpa.l     a4,a2  ; src L1372: cmpa.l data,a2
        bcs.w      no_memory  ; src L1373: bcs no_memory; target $000013ee
;
; MEGA_MOVE; copy D0.L bytes from (A0) to (DATA); handles ALL values
;
mega_move:
        tst.l      d0  ; src L1377: mega_move tst.l d0  Loony parameter?
        ble.s      moved  ; src L1378: ble.s moved; target $00000d74
move_how_many:
        moveq      #$20,d1  ; src L1380: moveq #32,d1  A bad way to move 1-11 bytes!
        cmp.l      d1,d0  ; src L1381: cmp.l d1,d0
        bls.s      minimove  ; src L1382: bls.s minimove; target $00000db0
        move.l     a0,d1  ; src L1383: move.l a0,d1
