        move.l     a4,d1  ; src L1386: move.l data,d1
        btst       #$0,d1  ; src L1387: btst #0,d1
        beq.s      one_odd  ; src L1388: beq.s one_odd; target $00000d9e
        move.b     (a0)+,(a4)+  ; src L1389: move.b (a0)+,(data)+ Get 'em both on even boundaries
        subq.l     #1,d0  ; src L1390: subq.l #1,d0  One less byte to bother with!
        bne.s      big_move  ; src L1391: bne.s big_move Result is ALWAYS N.E! Misdirection for...; target $00000dfc
;
; Hidden copyright says 24A, 021 429 2612, \x7F 1986 SNG; disassembles as:
;
; OR.W D0,12(A6,D2.W)  MOVE.W D0,D4  ADDQ.W #4,12(A6,D2.W)
;
        dc.w       $817B,$394D,$3800,$587B  ; src L1397: dc.w $24A+'\x7F1',21+'98',429+'6S',2612+'NG'; ASCII |.{9M8.X{|
;
source_even:
        move.l     a4,d1  ; src L1399: source_even move.l data,d1 This word disassembles IN the copyright!
        btst       #$0,d1  ; src L1400: btst #0,d1
        bne.s      one_odd  ; src L1401: bne.s one_odd; target $00000d9e
;
; BIG_MOVE: This entry-point is used when moving D0 bytes (odd or even,
; but preferably lots) between EVEN values of A0 and DATA.
;
big_move:
        move.w     d0,d2  ; src L1406: big_move  move.w d0,d2  Save low bits of length for later
        lsr.l      #2,d0  ; src L1407: lsr.l #2,d0  Get a serious LONG WORD count, ignoring parts
        lea        $8506(a6),a2  ; src L1408: lea.l big_block-lowest(base),a2   Return point until last loop
        lea        $8e78(a6),a3  ; src L1409: lea.l long_table-lowest(base),a3   ** GWJ, moved out of loop
big_block:
        moveq      #$20,d1  ; src L1411: moveq #32,d1
