        bhi.s      move_longs  ; src L1413: bhi.s move_longs; target $00000e1c
last_block:
        add.l      d1,d0  ; src L1414: last_block add.l d1,d0  Restore remaining count
        SUB.l      d0,d1  ; src L1415: sub.l d0,d1  D1 is No. of moves to be skipped
        lea        $851c(a6),a2  ; src L1416: lea.l last_part-lowest(base),a2   Return address
        add.l      d1,d1  ; src L1417: add.l d1,d1  Scale for two-byte instructions
        jmp        $00(a3,d1.l)  ; src L1418: jmp 0(a3,d1.l)
;
move_longs:
        jmp        (a3)  ; src L1420: move_longs jmp (a3) ** GWJ, previously jumped to bottom of table
;
last_part:
        btst       #$1,d2  ; src L1423: btst #1,d2
        beq.s      even_words  ; src L1424: beq.s even_words; target $00000e26
        move.w     (a0)+,(a4)+  ; src L1425: move.w (a0)+,(data)+ Move any odd word
even_words:
        btst       #$0,d2  ; src L1426: even_words btst #0,d2
        beq.s      even_bytes  ; src L1427: beq.s even_bytes; target $00000e2e
        move.b     (a0)+,(a4)+  ; src L1428: move.b (a0)+,(data)+ And any odd byte
even_bytes:
        rts          ; src L1429: even_bytes rts; return via CPU stack
;
; CALL_ROM is used to call resident procedures and functions; (SP) points
; to the name-table offset for the ROM address (.W); it is followed by a
; byte count & concise (type & separator) parameter specification. Code
; continues from the next even address thereafter. When calling a function
; D5 should indicate the returned type expected (unlike in SUPERCHARGE).
;
; This LIGHTNING routine is general-purpose and thus less than optimal.
;
; Threaded calls have a different escape sequence to native ones -
; they invert the sign of their 'required type' to indicate this.
; JSR and RTS are used in native calls, but the JSR passes the parameter
; address and return is to a computed even address after them.
; In threaded calls this address is intercepted and used to set thread
; - return is to the original stacked address, and hence to another bit
; of threaded code... neat, eh?
;
thread_rom_proc:
        moveq      #$00,d5  ; src L1447: thread_rom_proc moveq #0,d5
