;
; The next routine READs a DATA value & coerces it to qdos_type D5.
; DATA values that start positive are string lengths (0-32766) or
; integer prefixes (32767). Negative starts sift out as follows:
; -0 (-32768) to 4095: negated float exponents; -4096 to -32766:
; short integers (values -3000 to 25670) - negate & subtract 7096
; for actual value; -32767 End of DATA.
;
easy_reading:
        move.l     $8ebe(a6),a0  ; src L1841: move.l data_pointer-lowest(base),a0
        move.w     (a0)+,d0  ; src L1842: move.w (a0)+,d0 Get first word of data-item
        bpl.s      int_or_string  ; src L1843: bpl.s int_or_string; target $000011e4
        cmpi.w     #$8001,d0  ; src L1844: cmpi.w #end_of_data,d0
        beq.w      end_of_file  ; src L1845: beq end_of_file; target $000013e6
        neg.w      d0  ; src L1846: neg.w d0  Make exponent positive
        cmpi.w     #$0fff,d0  ; src L1847: cmpi.w #4095,d0
        bls.s      good_exponent  ; src L1848: bls.s good_exponent; target $000011dc
        subi.w     #$1bb8,d0  ; src L1849: subi.w #7096,d0 Convert to integer, -3000 to 25670
        move.w     d0,-(a1)  ; src L1850: move.w d0,-(maths)
        bra.s      got_short_int  ; src L1851: bra.s got_short_int; target $00001202
