;
; GWJ, Fast float add one. The normal fast_add code is used if:
; (a) exponent_difference < 0 i.e. TOS must be denormalised
; (b) exponent_difference > 30
; With these cases filtered out the following facts are true:
; (a) If the result mantissa is positive, it must either be
; shifted 1 place right (use existing code) or is already
; normalised.
; (b) If the result mantissa is negative, it must either be
; shifted 1 place left or is already normalised.
; (c) Result zero is impossible (handled by existing code).
;
; This is called by FOR_FLOAT, so it must preserve A2 and A3.
;
; A table to give a quick denormalised one
        dc.w       $8000  ; src L1938: dc.w $8000  Here for awkward case where
; exponent_difference = 15
denormalised_one:
        dc.w       $4000,$2000,$1000,$0800  ; src L1941: dc.w $4000,$2000,$1000,$0800; ASCII |@. .....|
        dc.w       $0400,$0200,$0100,$0080  ; src L1942: dc.w $0400,$0200,$0100,$0080
        dc.w       $0040,$0020,$0010,$0008  ; src L1943: dc.w $0040,$0020,$0010,$0008; ASCII |.@. ....|
        dc.w       $0004,$0002,$0001  ; src L1944: dc.w $0004,$0002,$0001
;
