        bge.s      do_fast_way  ; src L1955: bge do_fast_way; target $000012b4
        clr.w      $fffc(a1)  ; src L1956: clr.w -4(maths)
        move.l     #$08034000,$fff8(a1)  ; src L1957: move.l #$08034000,-8(maths)
        bra.w      denorm_nos  ; src L1958: bra denorm_nos; target $00001326
;
