;
; The error handler addresses are zapped to avoid an infinite loop if another
; error or a CONTINUE occurs before a RETRY. RETRY unzaps both addresses.
; If another error handler is defined with a WHEN_ERROR, the address is
; automatically unzapped.
;
; WHEN_ERROR routines must do a RETRY at the end of their code; if not
; the parser inserts a CONTINUE which looks for the next outer error handler.
; error handling is done with the MATHS and DATA pointers of the most
; recent RETRY_HERE, and we always want error trapping to succeed if
; a WHEN_ERROR has been encountered. N.B. Global error handlers will
; get the latest RETRY_HERE MATHS & DATA, like local handlers.
;
retry_regs:
        lea        $805e(a6),a2  ; src L2159: retry_regs lea retry_dump-lowest(base),a2
