        beq.s      locals_gone2  ; src L2207: beq.s locals_gone2; target $00001474
        move.l     d0,a3  ; src L2208: movea.l d0,a3  a3 --> past local value
        move.l     (a3)+,a0  ; src L2209: movea.l (a3)+,a0  a0 --> vector table entry
