;
; CHANNEL_DETAILS is a combination address and flag. The address points to
; the current item in the channel table. The (insignificant) first byte
; is only clear when output to a channel is enabled (CHAN_OP_ON).
; 5.04 These values are packed for ease of saving by PRINTING_GOSUB.
;
; V 5.1 - "suppress_op" must be put outside the channel details for 32-bit
; addressing.
;
suppress_op:
        dc.b       $00  ; src L2618: suppress_op dc.b 0
        dc.b       $00  ; src L2619: ; even alignment before long-word storage; alignment padding
channel_details:
        dc.l       $00000000  ; src L2619: channel_details dc.l 0
