;
; To set the error window if PE
;
set_w:
        move.l     $eca4(pc),a0  ; src L2662: set_w  movea.l err_chan,a0
        move.l     a1,-(a7)  ; src L2663: move.l a1,-(sp)
set_w2:
        move.l     a0,d0  ; src L2664: set_w2  move.l a0,d0
        beq.s      set_w1  ; src L2665: beq set_w1  not PE - so use #0; target $00001d3e
        add.w      d0,d0  ; src L2666: add.w d0,d0
        add.w      d0,d0  ; src L2667: add.w d0,d0
;
; Now open err_chan for PE if needed. ** v 5.18 - AUG 01
;
; The Con channel is opened at the start and is available for early_errors
; but should be closed to allow PE to choose a possibly smaller main window
; before the start of the program proper
;
        bpl.s      set_w3  ; src L2675: bpl set_w3  Channel open; target $00001cfe
        bsr.w      ope_erch  ; src L2676: bsr ope_erch  open an error channel; target $00000c7e
        lea        $ec90(pc),a1  ; src L2677: lea err_chan,a1
        move.l     a0,(a1)  ; src L2678: move.l a0,(a1)
        bra.s      set_w2  ; src L2679: bra set_w2; target $00001ce8
;
set_w3:
        move.l     $ec84(pc),a1  ; src L2681: set_w3  movea.l sys_vars,a1
        move.l     $0078(a1),a1  ; src L2682: movea.l sv_chbas(a1),a1 Channel Base
        move.l     $00(a1,d0.w),a1  ; src L2683: movea.l (a1,d0.w),a1
        lea        $0018(a1),a1  ; src L2684: lea $18(a1),a1 point to outline size
        cmpi.w     #$01c0,(a1)  ; src L2685: cmpi.w #448,(a1)
        blt.s      set_w4  ; src L2686: blt set_w4  too small - set "normal" size; target $00001d1c
        cmpi.w     #$00b4,$0002(a1)  ; src L2687: cmpi.w #180,2(a1)
        bge.s      set_w5  ; src L2688: bge set_w5  big enough; target $00001d20
set_w4:
