; TEMPLATE 40: divide_float -- 164 copied code/data bytes; source L2848..L2914
; ========================================================================================
e_minus_float:
;
;
; DIVIDE_FLOAT is potentially slow, so it uses lots of optimisations:
; <1> If the dividend is zero it returns zero at once.
; <2> If the dividend and divisor have the same mantissa, the result
; mantissa is 1, and the exponent is DIVIDEND_EXP - DIVISOR_EXP + EXP_of_1;
; in other words, the result is an exact power of 2.
; <3> If the DIVISOR is an exact power of 2, the result is produced by
; adjusting the exponent of the dividend, preserving its mantissa.
; <4> Otherwise, QDOS is called if either operand mantissa differs from
; the 'previous' ones passed to the ROM. If the mantissae match, the result
; is synthesised by comparing exponents and scaling the 'previous' result.
;
; 13th November 2001
; If QDOS is called and an OVR occurs, the "old exponent difference"
; is set to 8192 (an impossible result). This prevents the "old answer"
; being used erroneously on a following occasion.
;
divide_float:
        move.l     $0002(a1),d0  ; src L2849: move.l 2(maths),d0 Test B, if RESULT := A / B
        beq.s      utterly_cosmic  ; src L2850: beq utterly_cosmic Division by 0 -> OVR 13/11/01; target $00001eb8
        lea        $0022(pc),a3  ; src L2851: point_a3_at divide_table
        cmp.l      (a3)+,d0  ; src L2852: cmp.l (a3)+,d0  Does B's mantissa match the last one?
        bne.s      binary_scale  ; src L2853: bne.s binary_scale; target $00001e86
        move.l     $0008(a1),d1  ; src L2854: move.l 8(maths),d1 Check A's mantissa
        beq.s      not_much  ; src L2855: beq.s not_much  Zero is easy to handle; target $00001e74
        cmp.l      (a3)+,d1  ; src L2856: cmp.l (a3)+,d1  Match old A as well?
        bne.s      compare_args  ; src L2857: bne.s compare_args; target $00001e92
        cmpi.w     #$2000,(a3)  ; src L2858: cmpi.w #8192,(a3) Did last division overflow? .
        beq.s      compare_args  ; src L2859: beq compare_args . . yes; target $00001e92
        move.w     (a3)+,d0  ; src L2860: move.w (a3)+,d0  Get old exponent difference
        move.l     (a3),$0008(a1)  ; src L2861: move.l (a3),8(maths) Set old result mantissa
        bra.s      fudge_exponent  ; src L2862: bra.s fudge_exponent; target $00001eaa
not_much:
        addq.l     #6,a1  ; src L2863: not_much  addq.l #float_size,maths
        bra.s      optimised  ; src L2864: bra.s optimised; target $00001ef2
;
divide_table:
        dc.l       $00000000  ; src L2867: dc.l 0  Old B mantissa
        dc.l       $00000000  ; src L2868: dc.l 0  Old A mantissa
        dc.w       $0000  ; src L2869: dc.w 0  Old exponent difference
        dc.l       $00000000  ; src L2870: dc.l 0  Previous result mantissa
;
binary_scale:
        cmpi.l     #$40000000,d0  ; src L2873: cmpi.l #mant_of_1,d0 Is divisor's mantissa 1?
        beq.s      mant_1  ; src L2874: beq.s mant_1; target $00001ea0
        move.l     $0008(a1),d1  ; src L2875: move.l 8(maths),d1 Does divisor match dividend?
compare_args:
        cmp.l      d1,d0  ; src L2877: cmp.l d1,d0
        bne.s      not_shift  ; src L2878: bne.s not_shift; target $00001ec0
        move.l     #$40000000,$0008(a1)  ; src L2879: move.l #mant_of_1,8(maths) Result is a power of two
        bra.s      compute_exp  ; src L2880: bra.s compute_exp; target $00001ea6
mant_1:
        tst.l      $0008(a1)  ; src L2881: mant_1  tst.l 8(maths)  0 / anything gives 0, in my book!
        beq.s      not_much  ; src L2882: beq.s not_much; target $00001e74
compute_exp:
