        SUB.w      (a1),d0  ; src L2887: sub.w (maths),d0 Exponent B = scale-down factor
        addq.l     #6,a1  ; src L2888: addq.l #float_size,maths Forget B
        add.w      (a1),d0  ; src L2889: add.w (maths),d0
        move.w     d0,(a1)  ; src L2890: move.w d0,(maths)
        cmp.w      #$0fff,d0  ; src L2891: cmp.w #4095,d0  Check exponent is valid
        bls.s      optimised  ; src L2892: bls.s optimised; target $00001ef2
